using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Int64 n = Int64.Parse(Console.ReadLine());
            if (n % 2 == 1)
            {
                Console.Write("1");
            }
            else Console.Write("2");
        }
    }
}
